// Telemetry stream — explicit buffer and drop policy, batched to the UI
fun telemetryFlow(): Flow<List<Sample>> =
  socket.messages
    .map { it.toSample() }
    .buffer(capacity = 256, onBufferOverflow = BufferOverflow.DROP_OLDEST)
    .chunkedByTime(100)          // custom operator: batch every 100ms, no stdlib equivalent

// Compose UI — render a rolling window, never the whole history
@Composable
fun TelemetryChart(stream: Flow<List<Sample>>) {
  var window by remember { mutableStateOf<List<Sample>>(emptyList()) }
  LaunchedEffect(stream) {
    stream.collect { batch -> window = (window + batch).takeLast(500) }
  }
  LineChart(samples = window)
}

// Reconnect and resume from the last sequence number, not from zero
suspend fun connectWithResume(lastSeq: Long?): WebSocketSession {
  var attempt = 0
  while (true) {
    try {
      return ws.connect("/stream?from=\${lastSeq ?: 0}")
    } catch (e: IOException) {
      val backoff = (500L shl attempt.coerceAtMost(6)) + Random.nextLong(0, 500)
      delay(backoff.coerceAtMost(30_000))
      attempt++
    }
  }
}

// Persist progress inside the same transaction as the data — crash-safe resume
suspend fun onBatch(batch: List<Sample>) {
  db.transaction {
    samplesDao.insertAll(batch.map { it.toEntity() })
    metaDao.setLastSeq(batch.last().seq)
  }
}

class AppMessagingService : FirebaseMessagingService() {

  override fun onNewToken(token: String) {
    // Fires on install, restore, data clear, and rotation
    tokenSyncScheduler.enqueue(token)
  }

  override fun onMessageReceived(message: RemoteMessage) {
    val messageId = message.data["message_id"] ?: return
    if (!seenIds.add(messageId)) return              // de-dup re-sends

    val route = message.data["route"] ?: "home"      // a route, not a class name
    notify(
      channelId = message.data["category"] ?: "general",
      intent = deepLinkIntent(route),
      collapseKey = message.collapseKey
    )
    syncScheduler.requestSync()                      // push is a hint to sync
  }
}

