  FirebaseMessaging.getInstance().deleteToken().await()
}

// Shared code owns the logic; the platform owns the scheduling
interface SyncScheduler {
  fun schedulePeriodic()
  fun requestExpedited()
}

class AndroidSyncScheduler(private val ctx: Context) : SyncScheduler {
  override fun schedulePeriodic() {
    val work = PeriodicWorkRequestBuilder<SyncWorker>(4, TimeUnit.HOURS)
      .setConstraints(
        Constraints.Builder()
          .setRequiredNetworkType(NetworkType.CONNECTED)
          .setRequiresBatteryNotLow(true)
          .build()
      )
      .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 1, TimeUnit.MINUTES)
      .build()

    WorkManager.getInstance(ctx)
      .enqueueUniquePeriodicWork("sync", ExistingPeriodicWorkPolicy.KEEP, work)
  }
}

