@Entity(tableName = "outbox")
data class PendingOp(
  @PrimaryKey val opId: String = uuid4().toString(),   // idempotency key
  val entityId: String,
  val type: OpType,
  val payload: String,
  val baseVersion: Long,                               // optimistic concurrency
  val createdAt: Long
)

suspend fun editNote(id: String, body: String) = db.withTransaction {
  val note = notes.get(id)
  notes.upsert(note.copy(body = body, dirty = true))   // UI updates now
  outbox.insert(
    PendingOp(entityId = id, type = OpType.UPDATE, payload = body, baseVersion = note.version)
  )
}

suspend fun drain() = outbox.oldestPerEntity().forEach { op ->
  when (val r = api.push(op)) {
    is Ok -> { notes.applyServer(r.entity); outbox.delete(op.opId) }
    is Conflict -> conflicts.record(op, r.serverEntity)   // ask, do not guess
    is Retryable -> return@forEach                        // keep order, try later
  }
}

// Version gate, checked on launch and on resume
@Serializable
data class VersionPolicy(val minSupported: Int, val recommended: Int, val storeUrl: String)

suspend fun checkVersion(current: Int): Gate = when {
  current < policy.minSupported -> Gate.Block(policy.storeUrl)   // blocking screen
  current < policy.recommended -> Gate.Nag(policy.storeUrl)      // dismissible
  else -> Gate.Ok
}

