private val query = MutableStateFlow("")

val results: StateFlow<SearchUi> = query
  .map { it.trim() }
  .distinctUntilChanged()
  .debounce(250)
  .flatMapLatest { q ->                       // cancels the previous request
    if (q.length < 2) flowOf(SearchUi.Recent(history.recent()))
    else flow {
      emit(SearchUi.Local(local.search(q)))    // instant, from the local index
      emit(SearchUi.Remote(q, cache.getOrPut(q) { api.suggest(q) }))
    }.catch { emit(SearchUi.Error(q)) }
  }
  .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), SearchUi.Idle)

// Late responses still happen: drop anything that is no longer the current query
fun render(ui: SearchUi) {
  if (ui is SearchUi.Remote && ui.query != query.value) return
  show(ui)
}
